import { Component, h, Prop } from '@stencil/core';
import { State, Watch } from '@stencil/core/internal';

@Component({
  tag: 'std-small-rounded-progress',
  styleUrl: 'std-small-rounded-progress.css',
  shadow: true
})
export class StdSmallRoundedProgressComponent {
  @Prop() progress: string;

  @State() strokeDasharray: string;
  @State() strokeDashoffset: string;

  componentWillLoad() {
    this.renderStroke();
  }

  renderStroke() {
    const radius = 9;

    const circumference = 2 * Math.PI * radius;
    const offset = circumference * (1 - +this.progress / 100);

    this.strokeDasharray = circumference.toString();
    this.strokeDashoffset = offset.toString();
  }

  @Watch('progress')
  onWatchProgress(newValue: string) {
    this.progress = newValue;
    this.renderStroke();
  }

  render() {
    return (
      <svg class="js-small-rounded-progress w-6 h-6" viewBox="0 0 24 24" fill="none" data-progress="20">
        <rect x="3" y="3" width="18" height="18" rx="9" stroke="white" stroke-width="2"></rect>
        <rect x="2.9375" y="2.9375" width="18" height="18" rx="9" stroke="#CEDEE7" stroke-width="0.5"></rect>
        <circle
          cx="11.9375"
          cy="12.0625"
          r="9"
          transform="rotate(-90 11.9375 12.0625)"
          stroke="#EC0000"
          stroke-dasharray={this.strokeDasharray}
          stroke-dashoffset={this.strokeDashoffset}
          stroke-width="2"
          stroke-linecap="round"></circle>
      </svg>
    );
  }
}
